  function phoneChrome(title,sub,main,active='home',offline=false){return `<div class="mobile-workbench"><aside class="mobile-notes"><h3>${title}</h3><div class="mobile-note">Экран мобильного приложения Android/iOS. Крупные touch targets и понятные статусы.</div><div class="mobile-note">Критические состояния обозначаются текстом и иконкой, не только цветом.</div><div class="mobile-note">Offline-события сохраняют client_time, геоданные и idempotency key.</div></aside><div class="phone-stage"><div class="phone"><div class="phone-notch"></div><div class="phone-screen"><div class="phone-status"><span>09:41</span><span>${offline?'Нет сети':'5G'} · 92%</span></div><div class="mobile-top"><div style="flex:1"><h2>${title}</h2><p>${sub}</p></div>${offline?pill('OFFLINE','warning'):pill('ONLINE','success')}</div><main class="mobile-main">${offline?`<div class="offline-banner">${ico('wifiOff')} Нет сети. Действия будут синхронизированы позже.</div>`:''}${main}</main><nav class="mobile-nav">${[['home','Главная','home'],['shift','Смена','clock'],['patrol','Обход','route'],['notifications','События','bell'],['profile','Профиль','user']].map(([id,t,ic])=>`<div class="mnav ${active===id?'active':''}" data-nav="mobile:${id}">${ico(ic)}${t}</div>`).join('')}</nav></div></div></div></div>`}
  function mobileLogin(otp=false){return `<div class="proto-root"><div class="proto-frame"><div class="phone-stage" style="min-height:900px"><div class="phone"><div class="phone-notch"></div><div class="phone-screen"><div class="phone-status"><span>09:41</span><span>5G · 92%</span></div><main class="mobile-main" style="display:flex;flex-direction:column;justify-content:center;padding:32px 22px"><div class="brand-mark" style="width:54px;height:54px;border-radius:17px;margin-bottom:22px">Ч</div>${otp?`<h2 style="font-size:23px;margin:0 0 7px">Введите код</h2><p style="color:var(--muted);font-size:11px">Код отправлен на +7 ••• •••-45-67</p><div class="otp" style="gap:6px;margin:22px 0">${Array.from({length:6},(_,i)=>`<input style="width:46px" maxlength="1" value="${i<2?i+3:''}">`).join('')}</div><button class="m-btn" data-nav="mobile:home">Продолжить</button><button class="m-btn secondary" style="margin-top:8px" data-toast="Новый код отправлен">Получить новый код</button>`:`<h2 style="font-size:25px;margin:0 0 7px">ЧОППРО</h2><p style="color:var(--muted);font-size:11px;margin-bottom:24px">Рабочее приложение сотрудника охраны</p><div class="field"><label>Номер телефона</label><input value="+7 999 123-45-67"></div><button class="m-btn" style="margin-top:12px" data-nav="mobile:otp">Получить код</button><p style="color:var(--muted);font-size:9px;text-align:center;margin-top:16px">Продолжая, вы подтверждаете использование рабочего номера телефона.</p>`}</main></div></div></div></div></div>`}
  function mobileHome(){return phoneChrome('Сегодня','Вторник, 29 сентября',`<div class="m-card" style="background:linear-gradient(135deg,#355fe9,#6657dd);color:#fff;border:0"><div style="display:flex;justify-content:space-between;align-items:center"><div><span style="font-size:9px;opacity:.8">ТЕКУЩАЯ СМЕНА</span><h3 style="font-size:16px;margin-top:4px">БЦ Север · КПП-1</h3></div><span class="tag" style="background:rgba(255,255,255,.17);color:#fff">08:00–20:00</span></div><p style="color:#e9edff">До завершения смены 10 ч 12 мин</p><button class="m-btn" style="background:#fff;color:#3153c5" data-nav="mobile:shift">Открыть смену</button></div><div class="m-actions"><div class="m-action" data-nav="mobile:qr">${ico('qr')}Сканировать QR</div><div class="m-action" data-nav="mobile:patrol">${ico('route')}Начать обход</div><div class="m-action" data-nav="mobile:incident">${ico('alert')}Происшествие</div><div class="m-action" data-nav="mobile:offline">${ico('refresh')}Синхронизация</div></div><div class="m-card" style="margin-top:11px"><h3>Ближайшее действие</h3><p>10:00 · Обход «Утренний» · 3 контрольные точки</p><div class="progress"><span style="width:18%"></span></div></div>`,'home')}
  function mobileShift(){return phoneChrome('Текущая смена','БЦ Север · КПП-1',`<div class="m-card"><div style="display:flex;justify-content:space-between"><div><span style="font-size:9px;color:var(--muted)">08:00–20:00</span><h3>КПП-1</h3></div>${pill('IN PROGRESS','success')}</div><p>Москва, Ленинградский пр-т, 21</p><div class="gps-row">${ico('pin')} Вы на объекте · 18 м · точность 7 м</div></div><div class="m-card"><h3>Инструкция поста</h3><p>Версия 3.1 · подтверждена сегодня в 08:02</p><button class="m-btn secondary" data-nav="mobile:instruction">Открыть инструкцию</button></div><div class="m-actions"><div class="m-action" data-nav="mobile:checkin">${ico('check')}Check-out</div><div class="m-action" data-nav="mobile:qr">${ico('qr')}QR сканер</div></div><div class="m-card" style="margin-top:11px"><h3>События смены</h3>${mini('check','07:51 Check-in','VALID · online','success')}${mini('route','10:00 Обход','Запланирован','info')}</div>`,'shift')}
  function mobileInstruction(){return phoneChrome('Инструкция','КПП-1 · версия 3.1',`<div class="m-card"><span class="tag primary">Актуальная версия</span><h3 style="margin-top:10px">Порядок несения службы</h3><p>1. Контролировать вход посетителей и регистрацию транспорта.</p><p>2. Проверять действительность пропусков.</p><p>3. При происшествии действовать по категории и цепочке эскалации.</p><p>4. Не передавать рабочий QR-код третьим лицам.</p></div><div class="m-card"><div style="display:flex;gap:9px"><input type="checkbox" checked><div><h3>С инструкцией ознакомлен</h3><p>Подтверждено 29.09.2026 в 08:02</p></div></div></div>`,'shift')}
  function mobileCheckin(result=false){if(result)return phoneChrome('Check-in','Результат проверки',`<div class="m-card" style="text-align:center;padding:28px 18px"><div class="mini-icon success" style="width:54px;height:54px;margin:0 auto 13px">${ico('check')}</div><h3 style="font-size:18px">Вы заступили на смену</h3><p>Событие подтверждено сервером</p>${pill('VALID','success')}<div style="height:18px"></div><div class="grid cols-2" style="gap:8px;text-align:left"><div class="m-card"><strong>07:51</strong><p>Время</p></div><div class="m-card"><strong>18 м</strong><p>До точки</p></div><div class="m-card"><strong>7 м</strong><p>Точность GPS</p></div><div class="m-card"><strong>QR v7</strong><p>Токен</p></div></div></div><button class="m-btn" data-nav="mobile:home">На главную</button>`,'home');return phoneChrome('Заступление','Шаг 1 из 3',`<div class="m-card"><h3>БЦ Север · КПП-1</h3><p>Смена 08:00–20:00 · check-in доступен</p></div><div class="m-card"><h3>1. Геолокация</h3><div class="gps-row">${ico('pin')} 18 м от поста · точность 7 м</div></div><div class="m-card"><h3>2. QR поста</h3><p>Отсканируйте QR-код на КПП-1.</p><button class="m-btn secondary" data-nav="mobile:qr">Открыть сканер</button></div><button class="m-btn" data-nav="mobile:checkresult">Подтвердить check-in</button>`,'shift')}
